-- Named attacks pay once and store independent follow-up steps on the instance.
UPDATE dndshare.item_type SET fields=fields || jsonb_build_array($weapon_use_field${"key": "weapon_uses", "name": "Особое применение оружия", "type": "object_array", "fields": [{"key": "title", "name": "Название режима", "type": "text", "hint": "Название режима в меню атаки и в блоке применения под оружием."}, {"key": "key", "name": "Ключ", "type": "text"}, {"key": "attack_mode", "name": "Способ атаки", "type": "select", "default": "thrown", "options": [{"value": "thrown", "label": "Метание с характеристикой оружия"}, {"value": "melee", "label": "Рукопашная атака"}, {"value": "ranged", "label": "Дальняя атака"}], "hint": "Метание использует выбранную характеристику оружия. Бонусы и владение рассчитываются как при обычной атаке."}, {"key": "range_ft", "name": "Дистанция, футы", "type": "int", "default": 60, "hint": "Максимальная дистанция особой атаки в футах; для области-линии также задаёт её длину.", "min": 1, "max": 10000}, {"key": "resource_cost", "name": "Расход при атаке", "type": "int", "default": 1, "hint": "Сколько единиц ресурса потратить при броске атаки, даже если он промахнулся. Шаги не оплачиваются повторно.", "min": 0, "max": 100}, {"key": "resource_key", "name": "Ресурс", "type": "text"}, {"key": "steps", "name": "Шаги после атаки", "type": "object_array", "fields": [{"key": "title", "name": "Название шага", "type": "text", "hint": "Название отдельного шага после атаки: например, урон по линии или по конечной цели."}, {"key": "key", "name": "Ключ", "type": "text"}, {"key": "kind", "name": "Что бросаем", "type": "select", "default": "damage", "options": [{"value": "damage", "label": "Отдельный урон"}, {"value": "weapon_damage", "label": "Урон оружия при попадании + добавка"}], "hint": "Отдельный урон бросается независимо от попадания. Урон оружия включает основу и эту добавку только при попадании."}, {"key": "dice", "name": "Кость", "type": "select", "default": "d6", "options": [{"value": "d4", "label": "к4"}, {"value": "d6", "label": "к6"}, {"value": "d8", "label": "к8"}, {"value": "d10", "label": "к10"}, {"value": "d12", "label": "к12"}, {"value": "d20", "label": "к20"}, {"value": "d100", "label": "к100"}]}, {"key": "dice_count", "name": "Количество костей", "type": "int", "default": 1, "min": 1, "max": 100, "hint": "Число костей отдельного урона или добавки к урону оружия. Крит для попадания удвоит их автоматически."}, {"key": "damage_type", "name": "Тип урона", "type": "suggest", "suggest_id": 12}, {"key": "requirements", "name": "Условия", "type": "text_array"}, {"key": "save", "name": "Спасбросок", "type": "object", "fields": [{"key": "ability", "name": "Характеристика", "type": "suggest", "suggest_id": 16}, {"key": "dc", "name": "Сложность", "type": "int", "min": 1, "max": 99, "hint": "Сложность спасброска, который совершает каждая затронутая цель."}, {"key": "half", "name": "Половина урона при успехе", "type": "bool", "hint": "Показывать половину выпавшего урона, округлённую вниз, для успешного спасброска."}]}, {"key": "area", "name": "Область", "type": "object", "fields": [{"key": "shape", "name": "Форма", "type": "select", "options": [{"value": "line", "label": "Линия"}]}, {"key": "width_ft", "name": "Ширина, футы", "type": "int", "min": 1, "max": 1000, "hint": "Ширина линии в футах. Её длина берётся из дистанции режима."}]}]}]}$weapon_use_field$::jsonb)
WHERE id=19 AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(fields) f WHERE f->>'key'='weapon_uses');

UPDATE dndshare.item SET data=jsonb_set(data,'{weapon_uses}',COALESCE(data->'weapon_uses','[]'::jsonb)||jsonb_build_array($lightning_throw${"key": "lightning_throw", "title": "Метнуть молнией", "attack_mode": "thrown", "range_ft": 120, "resource_cost": 1, "steps": [{"key": "line", "title": "Урон по линии", "kind": "damage", "dice": "d6", "dice_count": 4, "damage_type": 9, "requirements": ["Все существа на линии, кроме владельца копья и конечной цели.", "Действует независимо от попадания по конечной цели."], "save": {"ability": 2, "dc": 13, "half": true}, "area": {"shape": "line", "width_ft": 5}}, {"key": "target", "title": "Урон по цели", "kind": "weapon_damage", "dice": "d6", "dice_count": 4, "damage_type": 9, "requirements": ["При попадании по конечной цели."]}]}$lightning_throw$::jsonb))
WHERE id=284 AND name='Метательное копьё молнии' AND type_id=19 AND user_id IS NULL
 AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(data->'weapon_uses','[]'::jsonb)) r WHERE r->>'key'='lightning_throw');
